insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_129'
from (values
('127.878.d.1.A',3,'An Automotive Technology II student writes a detailed summary of a transmission leak diagnosis for the service file, covering symptoms, tests and the repair. This is:','["effective written communication throughout the course", "an unrelated essay", "a casual text", "avoiding documentation"]'::jsonb,0,'Detailed, accurate writing.','original'),
('127.878.d.1.A',4,'Which written entry best serves the next technician who works on the vehicle?','["''Looks okay''", "one that states the symptom, tests performed, findings and parts replaced", "''Done''", "''Car is weird''"]'::jsonb,1,'Complete records.','original'),
('127.878.d.1.B',3,'A service writer lists 1.8 hours of diagnosis, a $92 sensor and a $14 gasket on the repair order. She is:','["hiding costs", "avoiding quotes", "estimating the cost of parts and labor operations on a repair order", "guessing"]'::jsonb,2,'Estimating.','original'),
('127.878.d.1.B',4,'A job needs $140 in parts and 2.5 hours at $96 per hour. The estimate is:','["$480", "$335", "$236", "$380"]'::jsonb,3,'140 + 240 = 380.','original'),
('127.878.d.1.C',3,'A technician converts a measured 0.125 inch of rotor wear to a fraction and compares it to the specification. She is:','["using mathematical skills such as fractions and decimals", "guessing", "ignoring numbers", "avoiding math"]'::jsonb,0,'Decimal and fraction fluency.','original'),
('127.878.d.1.C',4,'A tire''s tread measures 6/32 inch and wears 1/32 inch every 5,000 miles. How many miles until it reaches 2/32 inch?','["5,000 miles", "20,000 miles", "10,000 miles", "30,000 miles"]'::jsonb,1,'4 × 5,000 = 20,000.','original'),
('127.878.d.1.D',3,'A student looks up the vehicle''s service history and a related technical bulletin before starting an electrical diagnosis. She is:','["skipping research", "guessing", "researching applicable vehicle and service information, including service history", "ignoring data"]'::jsonb,2,'Research first.','original'),
('127.878.d.1.D',4,'Reviewing a vehicle''s previous repair history can help a technician:','["ignore the complaint", "skip testing", "raise the price", "avoid repeating a failed repair and spot patterns"]'::jsonb,3,'History reveals patterns.','original'),
('127.878.d.2.A',3,'A student explains how the engine, transmission, driveshaft, differential and axles work together to move a car, and tests each in turn. She is:','["diagnosing the major components of a powered vehicle", "painting", "ignoring parts", "guessing"]'::jsonb,0,'Diagnose systems.','original'),
('127.878.d.2.A',4,'A clunk heard only when shifting from reverse to drive most likely points to:','["low washer fluid", "worn driveline or mount components", "a loose antenna", "a dim bulb"]'::jsonb,1,'Torque transfer.','original'),
('127.878.d.2.B',3,'A technician rocks the front wheels, then shakes a driveshaft joint to find play in the chassis and driveline. She is:','["washing the car", "painting", "diagnosing chassis and driveline components", "guessing"]'::jsonb,2,'Chassis and driveline.','original'),
('127.878.d.2.B',4,'A vibration that increases with road speed and is felt in the floor often traces to:','["low washer fluid", "a worn key fob", "a dim lamp", "an out-of-balance driveshaft or tire"]'::jsonb,3,'Speed-related vibration.','original'),
('127.878.d.2.C',3,'A technician reads a wiring schematic, a torque chart and a fluid diagram before starting a repair. She is:','["locating, reading and interpreting service documents", "using memory only", "ignoring documents", "guessing"]'::jsonb,0,'Read the documents.','original'),
('127.878.d.2.C',4,'On a wiring schematic, a line with an arrow-like triangle and a bar commonly represents a:','["fuse", "diode", "motor", "switch"]'::jsonb,1,'Symbols matter.','original'),
('127.878.d.2.D',3,'A technician checks the recommended service intervals in the maintenance schedule for a 60,000-mile service. She is:','["ignoring intervals", "skipping service", "locating the manufacturer''s recommended preventative maintenance schedule", "guessing"]'::jsonb,2,'Follow the schedule.','original'),
('127.878.d.2.D',4,'Following the manufacturer''s schedule helps protect the vehicle''s:','["paint color", "seat covers", "radio", "warranty and long-term reliability"]'::jsonb,3,'Schedule keeps warranty.','original'),
('127.878.d.2.E',3,'A technician follows a multi-point inspection form covering fluids, belts, hoses, tires, lights and brakes. She is performing:','["a preventative maintenance inspection", "a body repair", "a sale", "a paint job"]'::jsonb,0,'PM inspection.','original'),
('127.878.d.2.E',4,'On an inspection form, a worn belt should be marked as:','["fine", "needing replacement, with a note for the customer", "optional paint", "ignore"]'::jsonb,1,'Document needs.','original'),
('127.878.d.2.F',3,'A technician uses a thread chaser, a helical insert and an extractor to repair a stripped drain-plug hole and a snapped stud. She is performing:','["avoiding repair", "guessing", "common fastener and thread repair", "painting"]'::jsonb,2,'Thread repair.','original'),
('127.878.d.2.F',4,'A bolt that snaps flush with the surface can often be removed with:','["a hammer only", "more torque", "paint remover", "a screw extractor after drilling a pilot hole"]'::jsonb,3,'Extraction process.','original'),
('127.878.d.2.G',3,'A technician uses a micrometer to measure a brake rotor''s thickness and a dial indicator for runout, then compares the numbers to published specifications. She is:','["performing precision measurements and using published specifications to diagnose wear", "painting", "ignoring specs", "guessing"]'::jsonb,0,'Measure to spec.','original'),
('127.878.d.2.G',4,'If a rotor''s thickness variation is greater than the specification, the technician should:','["paint it", "resurface (within limits) or replace the rotor", "ignore it", "add grease"]'::jsonb,1,'Out of spec.','original'),
('127.878.d.2.H',3,'A technician follows a step-by-step plan: verify the complaint, check the basics, test, isolate the fault and verify the repair. She is employing:','["random guessing", "luck", "critical-thinking and structured problem-solving skills", "avoiding thought"]'::jsonb,2,'Structured diagnosis.','original'),
('127.878.d.2.H',4,'After repairing a fault, the final problem-solving step is to:','["paint the engine", "ignore the car", "send the bill only", "verify the repair and confirm the complaint is gone"]'::jsonb,3,'Verify fix.','original'),
('127.878.d.3.A',3,'A student inspects an air hammer''s hose and connection, wears hearing and eye protection, and keeps others clear before use. She is demonstrating:','["the proper and safe use of hand and power tools and equipment", "ignoring rules", "unsafe habits", "careless setup"]'::jsonb,0,'Safe tool use.','original'),
('127.878.d.3.A',4,'Compressed air should never be used to:','["inflate a tire", "blow dust off clothing or skin", "operate an air tool", "blow debris off a bench"]'::jsonb,1,'Injury risk.','original'),
('127.878.d.3.B',3,'A student recycles used antifreeze, brake fluid and oil filters in marked containers and explains why. She is discussing and demonstrating:','["careless disposal", "ignoring rules", "proper handling and disposal of environmentally hazardous materials", "dumping"]'::jsonb,2,'Hazmat.','original'),
('127.878.d.3.B',4,'Used coolant is hazardous because it:','["is harmless", "is clean water", "is edible", "is toxic to animals and people"]'::jsonb,3,'Antifreeze is poisonous.','original'),
('127.878.d.3.C',3,'A student connects a lab scope to a sensor wire and a scan tool to the data port to compare signals. She is demonstrating:','["the proper use of diagnostic tools and equipment", "using a hammer", "guessing", "painting"]'::jsonb,0,'Diagnostic tools.','original'),
('127.878.d.3.C',4,'An oscilloscope shows a technician:','["fuel octane", "a voltage signal''s pattern over time", "oil color", "tire tread"]'::jsonb,1,'Waveform display.','original'),
('127.878.d.3.D',3,'A student finds the torque sequence, fluid capacity and a wiring schematic in the service information system for a specific vehicle. She is:','["ignoring data", "guessing", "locating, reading and interpreting service repair information", "using memory only"]'::jsonb,2,'Service information.','original'),
('127.878.d.3.D',4,'A service information system is more reliable than a generic internet forum because it:','["is shorter", "has no errors ever", "has more pictures", "contains manufacturer-approved procedures and specifications"]'::jsonb,3,'Authoritative source.','original'),
('127.878.d.4.A',3,'A student inspects a power steering high-pressure hose for chafing and replaces a leaking fitting. She is:','["inspecting and replacing power steering hoses and fittings", "guessing", "painting", "ignoring leaks"]'::jsonb,0,'PS hose service.','original'),
('127.878.d.4.A',4,'A power steering fluid leak at a hose crimp most likely requires:','["ignoring it", "replacing the hose assembly", "adding tape", "adding more fluid only"]'::jsonb,1,'Crimped hose.','original'),
('127.878.d.4.B',3,'A student removes a hub, washes the bearing, checks the race, repacks it with fresh grease and installs a new seal. She is:','["guessing", "avoiding service", "removing, cleaning, inspecting, repacking and installing wheel bearings and replacing seals", "painting"]'::jsonb,2,'Bearing service.','original'),
('127.878.d.4.B',4,'After installing a repacked bearing, the nut should be tightened according to:','["a random torque", "whatever feels loose", "no specification", "the manufacturer''s procedure and specification"]'::jsonb,3,'Follow spec.','original'),
('127.878.d.4.C',3,'A student presses a damaged bearing race from a hub and installs a new race squarely with a driver. She is:','["replacing a wheel bearing and race", "guessing", "painting", "avoiding repair"]'::jsonb,0,'Race replacement.','original'),
('127.878.d.4.C',4,'A new bearing race should be installed:','["crooked", "squarely and fully seated with the proper driver", "with a hammer only", "loosely"]'::jsonb,1,'Seat evenly.','original'),
('127.878.d.4.D',3,'Before working near an airbag module, a technician follows the manufacturer''s steps to disconnect the battery and wait for the stored energy to drain. She is:','["tuning a radio", "washing the car", "disabling the supplemental restraint system", "painting"]'::jsonb,2,'Disable SRS.','original'),
('127.878.d.4.D',4,'After re-enabling an SRS system, the technician should:','["disconnect the battery", "ignore the dash", "leave it disabled", "verify that the warning light operates and then goes out"]'::jsonb,3,'Verify SRS.','original'),
('127.878.d.4.E',3,'A student compresses a strut spring with a rated spring compressor, removes the strut and inspects the strut mount and bearing. She is:','["inspecting, removing and replacing shock absorbers and struts and inspecting mounts", "ignoring parts", "guessing", "painting"]'::jsonb,0,'Strut service.','original'),
('127.878.d.4.E',4,'A coil spring should be handled with a spring compressor because it:','["is fragile", "stores a large amount of energy that can cause injury", "is hot", "is magnetic"]'::jsonb,1,'Stored energy.','original'),
('127.878.d.4.F',3,'A student removes the tire from a wheel with a pressure sensor, checks the sensor and valve stem, and remounts it without damaging the sensor. She is:','["painting", "avoiding tire work", "dismounting, inspecting and remounting a tire on a wheel equipped with a pressure sensor", "guessing"]'::jsonb,2,'TPMS wheel care.','original'),
('127.878.d.4.F',4,'When changing a tire on a wheel with a TPMS sensor, the technician should rotate the bead breaker away from the valve to:','["improve grip", "save time", "shine the wheel", "avoid damaging the sensor"]'::jsonb,3,'Protect the sensor.','original'),
('127.878.d.4.G',3,'A student inspects a rear suspension''s lateral links, trailing arms, leaf springs and bushings for wear and bent parts. She is:','["inspecting the rear suspension system", "ignoring parts", "guessing", "painting"]'::jsonb,0,'Rear suspension.','original'),
('127.878.d.4.G',4,'A cracked rear leaf spring or a worn bushing may cause:','["a quieter radio", "poor handling and uneven tire wear", "a cooler engine", "better steering"]'::jsonb,1,'Suspension wear.','original'),
('127.878.d.4.H',3,'A student inspects tires for cupping and feathering, checks the size and the load and speed ratings against the placard. She is:','["painting", "guessing", "inspecting tire condition and wear patterns and checking for the correct size and application", "ignoring tires"]'::jsonb,2,'Tire inspection.','original'),
('127.878.d.4.H',4,'Wear on both outer edges of a tire most often indicates:','["over-inflation", "good alignment", "a new tire", "chronic under-inflation"]'::jsonb,3,'Edge wear means low pressure.','original'),
('127.878.d.4.I',3,'A student measures the distance from the wheel center to the fender lip at each corner before an alignment. She is:','["performing a pre-alignment inspection and measuring vehicle ride height", "painting", "guessing", "ignoring heights"]'::jsonb,0,'Ride height.','original'),
('127.878.d.4.I',4,'A pre-alignment inspection is important because an alignment cannot be accurate if the vehicle has:','["a new radio", "worn or damaged steering and suspension parts", "fresh paint", "clean tires"]'::jsonb,1,'Fix worn parts first.','original'),
('127.878.d.4.J',3,'A student submerges a tire and wheel assembly in water and watches for bubbles at the bead and valve. She is:','["guessing", "painting", "inspecting a tire and wheel assembly for air loss", "ignoring leaks"]'::jsonb,2,'Leak test.','original'),
('127.878.d.4.J',4,'Bubbles forming at the rim edge of a tire usually indicate a leak at the:','["sidewall logo", "tread", "valve cap color", "bead seal"]'::jsonb,3,'Bead leak.','original'),
('127.878.d.4.K',3,'A student compares a direct TPMS, which has a sensor in each wheel, with an indirect system that uses wheel-speed data, and checks the dash indicator. She is:','["identifying and testing indirect and direct TPMSs and the instrument panel indicator", "painting", "ignoring TPMS", "guessing"]'::jsonb,0,'TPMS types.','original'),
('127.878.d.4.K',4,'An indirect TPMS estimates low pressure by:','["reading a barometer", "comparing the rotational speed of each wheel", "reading the tire tread", "measuring tire temperature"]'::jsonb,1,'Smaller tires spin faster.','original'),
('127.878.d.4.L',3,'A student reviews the steps to remove and replace a wheel sensor, including relearning its position with a scan tool. She is:','["painting", "ignoring sensors", "demonstrating knowledge of the steps to remove and replace TPMS sensors", "guessing"]'::jsonb,2,'TPMS replacement.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_129'
from (values
('127.878.d.4.L',4,'After a TPMS sensor is replaced, the technician must often:','["leave the light on", "skip the step", "paint the wheel", "perform a relearn procedure so the system recognizes the sensor"]'::jsonb,3,'Relearn.','original'),
('127.878.d.4.M',3,'A student removes a front-wheel-drive hub assembly and CV axle, inspects the bearing and seals and reinstalls them. She is:','["inspecting, removing and replacing FWD bearings, hubs and seals", "painting", "ignoring wear", "guessing"]'::jsonb,0,'FWD hub service.','original'),
('127.878.d.4.M',4,'A front wheel bearing that growls and gets louder when turning left probably has:','["a loose wiper", "wear in the bearing on the loaded (right) side", "a dead battery", "a flat tire"]'::jsonb,1,'Load transfer.','original'),
('127.878.d.5.A',3,'A student explains that a chafed power wire touching the frame will blow a fuse, while a corroded connector adds unwanted resistance. She is demonstrating knowledge of:','["brake wear", "fuel flow", "the causes and effects of shorts, opens and resistance problems in circuits", "tire wear"]'::jsonb,2,'Circuit faults.','original'),
('127.878.d.5.A',4,'High resistance in a headlight connection will most likely cause:','["no effect", "brighter light", "a cooler wire", "dim light and heat at the connector"]'::jsonb,3,'Voltage drop.','original'),
('127.878.d.5.B',3,'A technician connects an ammeter in series after the car sleeps for 30 minutes and finds a 200 milliamp draw. She is:','["measuring key-off battery drain (parasitic draw)", "testing the starter", "testing oil", "testing tires"]'::jsonb,0,'Parasitic draw test.','original'),
('127.878.d.5.B',4,'A battery that is dead each morning, with a normal charging system, suggests:','["an overcharge", "an excessive parasitic draw", "a bad tire", "a perfect battery"]'::jsonb,1,'Draw drains battery.','original'),
('127.878.d.5.C',3,'A technician heats a spliced wire, flows solder into it and covers it with heat-shrink tubing. She is:','["gluing a wire", "painting", "performing a solder repair of electrical wiring", "taping only"]'::jsonb,2,'Solder splice.','original'),
('127.878.d.5.C',4,'A good solder joint should look:','["burned black", "cracked", "dull and grainy", "smooth and shiny, not dull or lumpy"]'::jsonb,3,'Visual check.','original'),
('127.878.d.5.D',3,'A technician crimps a new terminal onto a wire and snaps it into a weather-pack connector. She is:','["replacing an electrical connector and terminal end", "painting", "avoiding repair", "guessing"]'::jsonb,0,'Terminal replacement.','original'),
('127.878.d.5.D',4,'A sealed connector in a wheel-well harness is used to:','["let in air", "keep water and dirt out of the terminals", "add voltage", "look neat"]'::jsonb,1,'Seal prevents corrosion.','original'),
('127.878.d.5.E',3,'Before disconnecting the battery, a technician plugs a memory saver into the diagnostic port so the radio presets and the settings are kept. She is:','["erasing settings", "ignoring memory", "maintaining or restoring electronic memory functions", "guessing"]'::jsonb,2,'Memory saver.','original'),
('127.878.d.5.E',4,'After a battery replacement, the technician may need to reset the:','["brake fluid", "oil level", "tire pressure only", "radio, clock and window auto-up learning"]'::jsonb,3,'Relearn settings.','original'),
('127.878.d.5.F',3,'A technician selects a 10-amp slow charge for a deeply discharged battery and monitors the temperature. She is:','["performing a slow battery charge according to the manufacturer''s recommendations", "painting", "guessing", "overcharging"]'::jsonb,0,'Slow charging.','original'),
('127.878.d.5.F',4,'A fast charge can damage a battery if it:','["is monitored", "is used too long or lets the battery overheat", "is short", "is cooled"]'::jsonb,1,'Heat damage.','original'),
('127.878.d.5.G',3,'A technician locates the body control module, the immobilizer antenna and the radio head unit on a vehicle diagram. She is:','["painting", "ignoring modules", "identifying electronic modules, security systems, radios and other accessories", "guessing"]'::jsonb,2,'Find modules.','original'),
('127.878.d.5.G',4,'An immobilizer system prevents a car from starting when it:','["is cold", "has a loose gas cap", "has low fuel", "does not recognize the key''s transponder code"]'::jsonb,3,'Security feature.','original'),
('127.878.d.5.H',3,'A technician measures the voltage lost across the starter cable while the engine cranks, along with the current draw. She is performing:','["a starter current draw test and a starter circuit voltage drop test", "a fuel test", "an oil test", "a tire test"]'::jsonb,0,'Starter tests.','original'),
('127.878.d.5.H',4,'A voltage drop of more than about 0.5 volts across a starter cable means the cable has:','["low draw", "excess resistance, often from a bad connection", "a perfect connection", "too little current"]'::jsonb,1,'Excess resistance.','original'),
('127.878.d.5.I',3,'A technician disconnects the battery, removes the starter''s mounting bolts and wires, installs a new starter and torques the bolts. She is:','["painting", "washing the car", "removing and installing a starter in a vehicle", "tuning the radio"]'::jsonb,2,'Starter replacement.','original'),
('127.878.d.5.I',4,'Before removing a starter, the technician should first:','["jack the front wheel", "remove the oil cap", "start the engine", "disconnect the negative battery cable"]'::jsonb,3,'Disconnect power.','original'),
('127.878.d.5.J',3,'A technician tests the ignition switch, neutral safety switch, relay and wires of the circuit that tells the starter to crank. She is:','["inspecting and testing the switches, connectors and wires of the starter control circuit", "ignoring wires", "painting", "guessing"]'::jsonb,0,'Control circuit.','original'),
('127.878.d.5.J',4,'If the starter does not click when the key is turned, but the battery is strong, one suspect is:','["the washer pump", "the starter relay or ignition switch", "the wiper blade", "a flat tire"]'::jsonb,1,'Control circuit fault.','original'),
('127.878.d.5.K',3,'A technician revs the engine to 2,500 rpm and measures the alternator''s output current and voltage, and compares them with spec. She is performing:','["a brake test", "a tire test", "a charging system output test", "a fuel test"]'::jsonb,2,'Output test.','original'),
('127.878.d.5.K',4,'An alternator that produces 12.0 volts with the engine at 2,500 rpm is:','["fully charged", "overcharging", "perfect", "not charging properly"]'::jsonb,3,'Needs 13.5–14.8 V.','original'),
('127.878.d.5.L',3,'A technician removes the drive belt, unplugs the alternator, removes the mounting bolts, inspects the pulley and reinstalls it. She is:','["removing, inspecting and re-installing an alternator", "painting", "guessing", "avoiding repair"]'::jsonb,0,'Alternator replacement.','original'),
('127.878.d.5.L',4,'After installing an alternator, the belt tension and alignment should be:','["left loose", "checked to prevent slipping and premature wear", "ignored", "painted"]'::jsonb,1,'Check tension.','original'),
('127.878.d.5.M',3,'A student learns that hybrid high-voltage cables are colored orange and that gloves rated for the voltage must be worn. She is identifying:','["tire pressure", "wiper speed", "system voltage and safety precautions associated with high-voltage systems", "oil capacity"]'::jsonb,2,'Orange means high voltage.','original'),
('127.878.d.5.M',4,'Before working on a hybrid''s high-voltage system, a technician should:','["start the engine", "touch the cables to test", "remove the radio", "disable the system using the manufacturer''s service disconnect procedure"]'::jsonb,3,'Disconnect HV.','original'),
('127.878.d.5.N',3,'A technician disconnects the battery, waits for the specified time and confirms the airbag light behaves normally after reconnecting. She is:','["disabling and enabling the airbag system and verifying the indicator", "guessing", "ignoring airbags", "painting"]'::jsonb,0,'Airbag service.','original'),
('127.878.d.5.N',4,'If the airbag light stays on after a repair, the technician should:','["cover it", "scan for stored SRS codes and correct the fault", "ignore it", "disconnect the battery"]'::jsonb,1,'Diagnose SRS.','original'),
('127.878.d.5.O',3,'A technician removes the screws, releases the clips, unplugs the switch harness and lifts off a door panel. She is:','["washing the car", "painting the door", "removing and reinstalling a door panel", "tuning a radio"]'::jsonb,2,'Door panel.','original'),
('127.878.d.5.O',4,'Plastic panel clips are best released using:','["a hammer", "a screwdriver and force", "pliers", "a trim removal tool"]'::jsonb,3,'Avoid breaking clips.','original'),
('127.878.d.5.P',3,'A student explains that a key fob sends a coded radio signal to unlock doors or start the engine from a distance. She is describing:','["the operation of keyless entry and remote-start systems", "a paint system", "a fuel system", "a tire system"]'::jsonb,0,'Keyless entry.','original'),
('127.878.d.5.P',4,'If a key fob stops working suddenly, the first thing to check is:','["the wipers", "the fob battery", "the tire pressure", "the oil"]'::jsonb,1,'Weak fob battery.','original'),
('127.878.d.6.A',3,'A technician drives the car on a quiet road, noting pedal feel, pulling and noises while braking firmly in a safe area. She is:','["racing", "ignoring", "describing a procedure for performing a road test to check brake system operation", "guessing"]'::jsonb,2,'Road test.','original'),
('127.878.d.6.A',4,'During a brake road test, a pull to the right when braking suggests:','["a perfect system", "a dead battery", "a clean windshield", "uneven braking force from a sticking caliper or hose"]'::jsonb,3,'Pull means uneven.','original'),
('127.878.d.6.B',3,'A technician measures how high the pedal sits, how far it travels and how much free play it has, then compares the numbers to spec. She is:','["measuring brake pedal height, reserve distance, travel and free play", "guessing", "painting", "ignoring spec"]'::jsonb,0,'Pedal measurements.','original'),
('127.878.d.6.B',4,'A pedal that goes nearly to the floor before the brakes engage may indicate:','["a perfect system", "a leak or air in the hydraulic system", "a clean filter", "a new tire"]'::jsonb,1,'Low pedal.','original'),
('127.878.d.6.C',3,'A student traces the red BRAKE lamp circuit to the parking brake switch, the fluid level sensor and the pressure differential switch. She is:','["guessing", "ignoring lights", "identifying components of the brake warning light system", "painting"]'::jsonb,2,'Warning light.','original'),
('127.878.d.6.C',4,'The brake warning light may glow when the:','["radio is on", "windows are open", "tank is full", "brake fluid level is low or the parking brake is applied"]'::jsonb,3,'Common triggers.','original'),
('127.878.d.6.D',3,'A technician pumps and holds the pedal while a helper opens the bleeder, watching for clear fluid with no bubbles. She is:','["bleeding and flushing the brake system", "washing the car", "painting", "tuning the radio"]'::jsonb,0,'Brake bleed.','original'),
('127.878.d.6.D',4,'Brake fluid should be flushed periodically because it:','["burns off", "absorbs moisture over time, lowering its boiling point", "gets sweeter", "gets thicker"]'::jsonb,1,'Hygroscopic.','original'),
('127.878.d.6.E',3,'A technician presses the pedal while a partner checks that the center and both rear stop lamps light, then checks the switch. She is:','["painting", "ignoring lights", "identifying and checking the operation of the brake stop light system", "guessing"]'::jsonb,2,'Stop lamp check.','original'),
('127.878.d.6.E',4,'If none of the stop lights work, a good first check is the:','["wiper blades", "oil level", "tire pressure", "brake light switch and fuse"]'::jsonb,3,'Check switch and fuse.','original'),
('127.878.d.6.F',3,'A student identifies the wheel-speed sensors, the yaw sensor and the hydraulic control unit used by traction and stability control. She is:','["identifying traction control and vehicle stability control system components", "guessing", "ignoring sensors", "painting"]'::jsonb,0,'Stability control parts.','original'),
('127.878.d.6.F',4,'Stability control helps a driver by:','["shutting off the engine", "applying individual brakes to correct a skid", "adding speed", "increasing noise"]'::jsonb,1,'Corrects skids.','original'),
('127.878.d.7.A',3,'A technician learns that the emissions monitors must complete a drive cycle before a car can pass a state inspection. She is describing:','["ignoring monitors", "guessing", "the importance of operating all OBD II monitors for repair verification", "painting"]'::jsonb,2,'Monitors verify repairs.','original'),
('127.878.d.7.A',4,'An OBD II ''not ready'' status after clearing codes means:','["the battery is dead", "the tires are low", "the car is broken", "the monitors have not finished running"]'::jsonb,3,'Not ready is normal initially.','original'),
('127.878.d.7.B',3,'A technician disables one cylinder at a time and watches the change in rpm to find a weak cylinder. She is performing:','["a cylinder power balance test", "an oil test", "a tire test", "a brake test"]'::jsonb,0,'Power balance.','original'),
('127.878.d.7.B',4,'If disabling one cylinder causes no change in rpm, that cylinder is:','["overworking", "not contributing power", "perfect", "too cool"]'::jsonb,1,'No change means weak.','original'),
('127.878.d.7.C',3,'A technician cranks the engine and records the compression on each cylinder with a gauge and compares to the specification. She is performing:','["a battery test", "a fuel test", "cylinder cranking and running compression tests", "a tire test"]'::jsonb,2,'Compression test.','original'),
('127.878.d.7.C',4,'Two adjacent cylinders with very low compression often indicate:','["a dead battery", "a perfect engine", "low tire pressure", "a blown head gasket between them"]'::jsonb,3,'Adjacent cylinders.','original'),
('127.878.d.7.D',3,'A technician pressurizes a cylinder with compressed air and listens for leaks at the intake, exhaust and radiator. She is performing:','["a cylinder leakage test", "a tire test", "a fuel test", "an oil test"]'::jsonb,0,'Leakage test.','original'),
('127.878.d.7.D',4,'Air heard hissing from the tailpipe during a leakage test points to a:','["bad tire", "leaking exhaust valve", "dead battery", "bad plug"]'::jsonb,1,'Exhaust valve.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
