insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_129'
from (values
('127.878.d.7.E',3,'A technician watches a scan tool''s coolant temperature reading as the engine warms and compares it to the thermostat spec. She is:','["measuring fuel", "measuring tires", "verifying the engine operating temperature", "measuring oil"]'::jsonb,2,'Check temperature.','original'),
('127.878.d.7.E',4,'A coolant temperature sensor that reads far below actual temperature can cause:','["a cooler engine", "a lean mixture", "better mileage", "a rich mixture and poor fuel economy"]'::jsonb,3,'Sensor affects fueling.','original'),
('127.878.d.7.F',3,'A technician replaces spark plugs on a four-cylinder engine, checks the gap and applies the correct torque. She is:','["removing and replacing spark plugs and inspecting secondary ignition components", "painting", "avoiding service", "guessing"]'::jsonb,0,'Spark plug service.','original'),
('127.878.d.7.F',4,'A spark plug with white, blistered insulator may indicate:','["a rich mixture", "overheating or a lean condition", "cold running", "normal wear"]'::jsonb,1,'Read the plug.','original'),
('127.878.d.7.G',3,'A technician uses a scan tool to read stored codes and freeze-frame data and records them on the repair order. She is:','["guessing", "ignoring data", "retrieving and recording diagnostic trouble codes and OBD II monitor status", "painting"]'::jsonb,2,'Record data.','original'),
('127.878.d.7.G',4,'Freeze-frame data on a scan tool shows:','["tire wear", "oil capacity", "paint code", "engine conditions at the moment the code was set"]'::jsonb,3,'Snapshot.','original'),
('127.878.d.8.A',3,'A technician cleans the mating surfaces, applies the specified sealer and installs a valve cover with a new gasket. She is:','["installing engine covers using gaskets, seals and sealers as required", "avoiding service", "painting", "guessing"]'::jsonb,0,'Cover installation.','original'),
('127.878.d.8.A',4,'Too much RTV sealer on a valve cover can:','["improve the seal", "squeeze inside and clog oil passages", "cool the engine", "reduce leaks"]'::jsonb,1,'Excess sealer.','original'),
('127.878.d.8.B',3,'A technician aligns the cam and crank timing marks, installs the new timing belt and rotates the engine by hand twice to confirm the marks line up. She is:','["painting", "avoiding service", "replacing a timing belt and verifying correct camshaft timing", "guessing"]'::jsonb,2,'Timing belt.','original'),
('127.878.d.8.B',4,'If a timing belt breaks on an interference engine, the result is likely:','["no damage", "quieter running", "better power", "bent valves and expensive damage"]'::jsonb,3,'Interference engines.','original'),
('127.878.d.8.C',3,'A technician pressurizes the radiator and adds UV dye to locate a seep in the cooling system. She is performing:','["cooling system pressure and dye tests to identify leaks", "painting", "avoiding tests", "guessing"]'::jsonb,0,'Cooling system leak test.','original'),
('127.878.d.8.C',4,'A cooling system that loses pressure but shows no external leak may have:','["a bad tire", "a leaking head gasket or heater core", "a dead battery", "a loose antenna"]'::jsonb,1,'Internal leak.','original'),
('127.878.d.8.D',3,'A technician drains the coolant, removes the thermostat housing and installs a new thermostat with the spring toward the engine. She is:','["guessing", "avoiding service", "removing, inspecting and replacing the thermostat and gasket or seal", "painting"]'::jsonb,2,'Thermostat replacement.','original'),
('127.878.d.8.D',4,'A thermostat that is stuck closed will make the engine:','["use less fuel", "run cold", "run quietly", "overheat quickly"]'::jsonb,3,'Stuck closed overheats.','original'),
('127.878.d.9.A',3,'A technician opens the glove box, releases the filter door and replaces a gray, leaf-filled cabin air filter. She is:','["identifying, locating and replacing the cabin air filter", "guessing", "painting", "avoiding service"]'::jsonb,0,'Cabin filter.','original'),
('127.878.d.9.A',4,'A cabin air filter is installed with the airflow arrow:','["hidden", "pointing in the direction of airflow", "at random", "against the flow"]'::jsonb,1,'Direction matters.','original'),
('127.878.d.9.B',3,'A technician rinses road debris from the condenser fins and checks for bent fins that block air. She is:','["guessing", "painting", "inspecting the A/C condenser for airflow restrictions", "ignoring debris"]'::jsonb,2,'Condenser check.','original'),
('127.878.d.9.B',4,'A blocked condenser can cause the A/C to blow warm air at idle because it:','["stores oil", "filters dust", "is too cool", "cannot reject heat to the outside air"]'::jsonb,3,'Heat rejection.','original'),
('127.878.d.9.C',3,'A customer complains of a musty smell when the A/C starts. The technician checks the evaporator drain and cabin filter. She is:','["identifying the source of A/C system odors", "painting", "ignoring smells", "guessing"]'::jsonb,0,'Odor diagnosis.','original'),
('127.878.d.9.C',4,'A musty odor from the vents is often caused by:','["a full tank", "moisture and mold on the evaporator", "a loose belt", "a new tire"]'::jsonb,1,'Moisture breeds mold.','original'),
('127.878.d.9.D',3,'A technician notes that a hybrid''s A/C compressor uses a high-voltage motor and special insulating oil, and follows the safety precautions. She is:','["guessing", "painting", "identifying hybrid vehicle A/C system electrical circuits and safety precautions", "ignoring risks"]'::jsonb,2,'Hybrid A/C.','original'),
('127.878.d.9.D',4,'Using the wrong refrigerant oil in a hybrid''s electric compressor can:','["reduce noise", "improve cooling", "save money", "damage the insulation and create an electrical hazard"]'::jsonb,3,'Conductive oil is a hazard.','original')
